/*
 * pio_drivers.c — RP2040 PIO driver implementations for the Open Programmer
 * Pico port.
 *
 * Wraps the autogenerated ow.pio.h / unio.pio.h headers and exposes the
 * per-protocol API declared in pio_drivers.h.
 *
 * Resource allocation (see pio_drivers.h header comment):
 *   pio0 SM0 — One-Wire   (ow.pio, 32 instr — fills the whole block)
 *   pio1 SM0 — UNI/O      (unio.pio, 6 instr)
 *
 * JTAG (TCK/TDI/TDO/TMS) and Microwire (uWCK/uWDI/uWDO) stay host-driven
 * software bit-bang on SIO, so their pins are NEVER handed to a PIO block.
 * This avoids FUNCSEL contention: pio_gpio_init() rewrites FUNCSEL to the
 * PIO function and never restores it, which would silently break gpio_put()
 * / gpio_get() on the same pin.
 *
 * Lazy pin ownership (method A): the OW and UNI/O SMs are loaded and
 * configured at boot, but their SM is left DISABLED and PIN_SDA stays on
 * SIO (open-drain, released). A protocol acquires the pin by calling
 * <proto>_pio_enter(), which sets PIN_SDA's FUNCSEL to the owning PIO block
 * and enables the SM; <proto>_pio_exit() disables the SM and restores
 * PIN_SDA to SIO open-drain. Because OW (pio0) and UNI/O (pio1) share
 * PIN_SDA, only one protocol owns the pin at a time — the host serialises
 * protocol switches, and exit() always runs before a different enter().
 *
 * The pin map matches hal.h:
 *   PIN_SDA = GP10  (OW + UNIO bus, open-drain, shared)
 *   PIN_SCL = GP11  (uWCK, SIO bit-bang)
 *   PIN_SDO = GP27  (uWDI, SIO bit-bang)
 *   PIN_CK  = GP6   (TCK,  SIO bit-bang)
 *   PIN_PGM = GP7   (TDI,  SIO bit-bang)
 *   PIN_D   = GP5   (TDO,  SIO bit-bang)
 *   PIN_A1  = GP15  (TMS,  SIO bit-bang)
 */
#include "pio_drivers.h"
#include "hal.h"
#include "hardware/clocks.h"
#include "hardware/pio.h"
#include "pico/stdlib.h"

// Autogenerated headers (built by pioasm from the .pio files).
#include "ow.pio.h"
#include "unio.pio.h"

// ---- State ---------------------------------------------------------------
static bool g_init_done = false;

// One-Wire
static PIO  ow_pio  = pio0;
static uint ow_sm   = 0;
static uint ow_off  = 0;
static float ow_div = 0.0f;

// UNI/O
static PIO  unio_pio = pio1;
static uint unio_sm  = 0;
static uint unio_off = 0;
static float unio_div = 0.0f;

// Tracks which protocol currently owns PIN_SDA so an accidental re-enter
// without exit is a no-op rather than a FUNCSEL fight.
enum sda_owner { SDA_NONE, SDA_OW, SDA_UNIO };
static enum sda_owner g_sda_owner = SDA_NONE;

// ---- Boot-time init ------------------------------------------------------
// Loads the OW and UNI/O programs into their PIO blocks and claims one SM
// each. The SMs are configured but left DISABLED; PIN_SDA is NOT touched
// (it stays on SIO from hal_init). Pin ownership is taken per-protocol via
// <proto>_pio_enter(). Safe to call multiple times.
void pio_drivers_init(void) {
    if (g_init_done) return;

    uint32_t sys_hz = clock_get_hz(clk_sys);

    // ---- One-Wire on pio0 SM0 (1 MHz = 1 us/cycle) ----
    ow_pio  = pio0;
    ow_sm   = pio_claim_unused_sm(ow_pio, true);
    ow_off  = pio_add_program(ow_pio, &ow_program);
    ow_div  = (float)sys_hz / 1000000.0f;

    // ---- UNI/O on pio1 SM0 (50 kbit/s bit rate = 10 us/half-bit) ----
    // unio.pio spends 2 PIO cycles per half-bit (out pindirs + jmp y--),
    // so a 10 us half-bit needs a 5 us PIO cycle -> SM at 200 kHz.
    // div = f_sys / 200e3.
    unio_pio = pio1;
    unio_sm  = pio_claim_unused_sm(unio_pio, true);
    unio_off = pio_add_program(unio_pio, &unio_program);
    unio_div = (float)sys_hz / 200000.0f;

    g_init_done = true;
}

// ---- One-Wire enter/exit -------------------------------------------------
void ow_pio_enter(void) {
    if (!g_init_done) pio_drivers_init();
    if (g_sda_owner == SDA_OW) return;            // already owning
    // UNI/O must release PIN_SDA first (mutual exclusion).
    if (g_sda_owner == SDA_UNIO) unio_pio_exit();
    // ow_program_init() does pio_gpio_init (FUNCSEL -> pio0), sets level 0,
    // releases pindirs, configures the SM and enables it. Idempotent.
    ow_program_init(ow_pio, ow_sm, ow_off, PIN_SDA, ow_div);
    g_sda_owner = SDA_OW;
}

void ow_pio_exit(void) {
    if (g_sda_owner != SDA_OW) return;
    pio_sm_set_enabled(ow_pio, ow_sm, false);
    // Restore PIN_SDA to SIO. pio_gpio_init() set FUNCSEL to the PIO0
    // function; gpio_put()/gpio_set_dir() (used by hal_od_init and the
    // UNIO bit-bang paths) only touch the SIO output/enable registers and
    // do NOT restore FUNCSEL, so we must do it explicitly here.
    gpio_set_function(PIN_SDA, GPIO_FUNC_SIO);
    // Now back on SIO: re-establish the open-drain idle state
    // (level 0, input/released) so the host's hal_od_* helpers work.
    hal_od_init(PIN_SDA);
    g_sda_owner = SDA_NONE;
}

// ---- One-Wire API --------------------------------------------------------
bool ow_pio_reset(void) {
    pio_sm_put_blocking(ow_pio, ow_sm, ow_CMD_RESET);
    uint32_t v = pio_sm_get_blocking(ow_pio, ow_sm);
    // Reset path does not include recovery; wait for the bus to settle
    // before the next command (spec requires >= 480 us total reset cycle;
    // the SM produced 480 us low + ~62 us presence sample = 542 us).
    busy_wait_us_32(420);
    return (v & 1) == 0;  // presence = bus low at sample time
}

void ow_pio_write_bit(uint bit) {
    pio_sm_put_blocking(ow_pio, ow_sm, bit ? ow_CMD_WRITE1 : ow_CMD_WRITE0);
    // The write slot takes ~70 us; wait for completion so back-to-back
    // writes keep the minimum 1-us recovery.
    busy_wait_us_32(70);
}

uint ow_pio_read_bit(void) {
    pio_sm_put_blocking(ow_pio, ow_sm, ow_CMD_READ);
    uint32_t v = pio_sm_get_blocking(ow_pio, ow_sm);
    return v & 1;
}

void ow_pio_write_byte(uint8_t byte) {
    for (int i = 0; i < 8; i++) {
        ow_pio_write_bit(byte & 1);
        byte >>= 1;
    }
}

uint8_t ow_pio_read_byte(void) {
    uint8_t byte = 0;
    for (int i = 0; i < 8; i++) {
        byte >>= 1;
        if (ow_pio_read_bit()) byte |= 0x80;
    }
    return byte;
}

// ---- UNI/O enter/exit ----------------------------------------------------
void unio_pio_enter(void) {
    if (!g_init_done) pio_drivers_init();
    if (g_sda_owner == SDA_UNIO) return;          // already owning
    // One-Wire must release PIN_SDA first (mutual exclusion).
    if (g_sda_owner == SDA_OW) ow_pio_exit();
    // unio_program_init() does pio_gpio_init (FUNCSEL -> pio1), sets level
    // 0, releases pindirs, configures the SM and enables it. Idempotent.
    unio_program_init(unio_pio, unio_sm, unio_off, PIN_SDA, unio_div);
    g_sda_owner = SDA_UNIO;
}

void unio_pio_exit(void) {
    if (g_sda_owner != SDA_UNIO) return;
    pio_sm_set_enabled(unio_pio, unio_sm, false);
    // Restore PIN_SDA to SIO. pio_gpio_init() set FUNCSEL to the PIO1
    // function; gpio_put()/gpio_set_dir() (used by hal_od_init and the
    // UNIO bit-bang paths) only touch the SIO output/enable registers and
    // do NOT restore FUNCSEL, so we must do it explicitly here.
    gpio_set_function(PIN_SDA, GPIO_FUNC_SIO);
    // Now back on SIO: re-establish the open-drain idle state
    // (level 0, input/released) so the host's hal_od_* helpers work.
    hal_od_init(PIN_SDA);
    g_sda_owner = SDA_NONE;
}

// ---- UNI/O API -----------------------------------------------------------
void unio_pio_emit_halfbits(uint16_t dir_pattern) {
    // The SM shifts 16 bits MSB-first from the OSR into pindirs. We push
    // the pattern left-justified? No — out_shift is right, so bit 0 of the
    // OSR is shifted first. We need MSB (bit 15) first, so we bit-reverse
    // the pattern before pushing.
    uint16_t rev = 0;
    for (int i = 0; i < 16; i++) {
        rev = (rev << 1) | (dir_pattern & 1);
        dir_pattern >>= 1;
    }
    pio_sm_put_blocking(unio_pio, unio_sm, (uint32_t)rev);
    // Drain the completion word so the FIFO doesn't fill up.
    (void)pio_sm_get_blocking(unio_pio, unio_sm);
}
